// services/api-gateway/src/middleware/tenant-resolver.js
export function tenantResolver(req, res, next) {
  const host = req.get('host');
  const subdomain = host.split('.')[0]; // e.g., acme.app.com

  const tenant = tenantMapping[subdomain];
  if (!tenant) {
    return res.status(404).json({ error: 'Unknown tenant' });
  }

  req.tenant = {
    id: tenant.id,
    schema: tenant.schema,
    realm: tenant.realm,
    name: tenant.name
  };

  next();
}

const tenantMapping = {
  'acme': { id: 'org_acme', schema: 'acme', realm: 'acme-realm', name: 'Acme Corp' },
  'globex': { id: 'org_globex', schema: 'globex', realm: 'globex-realm', name: 'Globex Inc.' }
