```javascript
// services/shared/database/tenant-pool.js
import { Pool } from 'pg';

class TenantPoolManager {
  constructor() {
    this.pools = new Map();
  }

  async getPool(tenantSchema) {
    if (this.pools.has(tenantSchema)) {
      return this.pools.get(tenantSchema);
    }

    const pool = new Pool({
      host: process.env.POSTGRES_HOST,
      port: process.env.POSTGRES_PORT,
      database: process.env.POSTGRES_DB,
      user: process.env.POSTGRES_USER,
      password: process.env.POSTGRES_PASSWORD,
      max: 10,
      idleTimeoutMillis: 30000,
      schema: tenantSchema // Set default schema
    });

    // Set search_path for this pool
    await pool.query(`SET search_path TO ${tenantSchema}`);

    this.pools.set(tenantSchema, pool);
    return pool;
  }
}

export const tenantPoolManager = new TenantPoolManager();
