### Repository Pattern with Schema Context

```javascript
// services/user-service/src/repositories/user.repository.js
import { tenantPoolManager } from '@shared/tenant-pool';

export class UserRepository {

  constructor(tenantSchema) {
    this.schema = tenantSchema;
  }

  async findAll(filter = {}, options = {}) {
    const pool = await tenantPoolManager.getPool(this.schema);
    const { page = 1, limit = 20 } = options;

    const query = {
      text: `SELECT * FROM users WHERE $1::jsonb @> to_jsonb($2) ORDER BY created_at DESC LIMIT $3 OFFSET $4`,
      values: [JSON.stringify(filter), JSON.stringify(filter), limit, (page - 1) * limit]
    };

    const result = await pool.query(query);
    return {
      data: result.rows,
      pagination: {
        page,
        limit,
        total: result.rows.length, // Simplified
      }
    };
  }

  async findById(id) {
    const pool = await tenantPoolManager.getPool(this.schema);
    const result = await pool.query('SELECT * FROM users WHERE id = $1', [id]);
    return result.rows[0] || null;
  }

  async create(userData) {
    const pool = await tenantPoolManager.getPool(this.schema);
    const result = await pool.query(
      `INSERT INTO users (email, first_name, last_name) VALUES ($1, $2, $3) RETURNING *`,
      [userData.email, userData.firstName, userData.lastName]
    );
    return result.rows[0];
  }

  async update(id, updates) {
    const pool = await tenantPoolManager.getPool(this.schema);
    const result = await pool.query(
      `UPDATE users SET email = $1, first_name = $2, last_name = $3 WHERE id = $4 RETURNING *`,
      [updates.email, updates.firstName, updates.lastName, id]
    );
    return result.rows[0];
  }

  async delete(id) {
    const pool = await tenantPoolManager.getPool(this.schema);
    await pool.query('DELETE FROM users WHERE id = $1', [id]);
    return true;
  }
}
