## Tenant Provisioning with Schema Creation

### Provisioning Service

```javascript
// services/org-service/src/services/provisioning.service.js
import { pool } from '@shared/database';
import { tenantPoolManager } from '@shared/tenant-pool';

export class ProvisioningService {

  async provisionOrganization(data) {
    const { name, domain, adminEmail } = data;
    const tenantSlug = domain.replace(/[^a-z0-9]/g, '_').toLowerCase();
    const schemaName = `tenant_${tenantSlug}`;

    try {
      // Create PostgreSQL schema
      await pool.query(`CREATE SCHEMA IF NOT EXISTS ${schemaName}`);

      // Create tenant-specific tables
      await pool.query(`
        CREATE TABLE IF NOT EXISTS ${schemaName}.users (
          id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
          email VARCHAR(255) UNIQUE NOT NULL,
          first_name VARCHAR(100),
          last_name VARCHAR(100),
          created_at TIMESTAMP DEFAULT NOW()
        )
      `);

      await pool.query(`
        CREATE TABLE IF NOT EXISTS ${schemaName}.projects (
          id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
          name VARCHAR(255) NOT NULL,
          created_at TIMESTAMP DEFAULT NOW()
        )
      `);

      // Create separate Keycloak realm for tenant
      await this.createTenantRealm(schemaName, name);

      // Create admin user in new realm
      await this.createAdminUser(schemaName, adminEmail);

      // Return tenant identifier
      return {
        tenantId: schemaName,
        schema: schemaName,
        realm: schemaName,
        loginUrl: `${process.env.APP_URL}/${schemaName}/login`
      };
    } catch (error) {
      await this.rollbackProvisioning(schemaName);
      throw error;
    }
  }

  async createTenantRealm(realmName, displayName) {
    // Use Keycloak Admin API to create a new realm
    const adminToken = await this.getAdminToken();
    await fetch(`${process.env.KEYCLOAK_URL}/admin/realms`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${adminToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        realm: realmName,
        displayName,
        enabled: true,
        sslRequired: 'external',
        registrationAllowed: false
      })
    });
  }

  async rollbackProvisioning(schemaName) {
    try {
      await pool.query(`DROP SCHEMA IF EXISTS ${schemaName} CASCADE`);
    } catch (err) {
      console.error('Rollback failed:', err);
    }
  }
}
```

