### Repository Pattern with org_id Isolation

```javascript
// services/user-service/src/repositories/user.repository.js
import { UserModel } from '../models/User.js';
import { ForbiddenError, NotFoundError } from '../utils/AppError.js';

export class UserRepository {

  constructor(orgId) {
    this.orgId = orgId;
  }

  async findAll(filter = {}, options = {}) {
    // ALWAYS enforce org_id filtering
    const query = {
      ...filter,
      org_id: this.orgId
    };

    const { page = 1, limit = 20, sort = { createdAt: -1 } } = options;

    const users = await UserModel.find(query)
      .select('-password')
      .limit(limit)
      .skip((page - 1) * limit)
      .sort(sort);

    const total = await UserModel.countDocuments(query);

    return {
      data: users,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit)
      }
    };
  }

  async findById(id) {
    const user = await UserModel.findOne({
      _id: id,
      org_id: this.orgId  // CRITICAL: Always filter by org_id
    }).select('-password');

    if (!user) {
      throw new NotFoundError('User');
    }

    return user;
  }

  async create(userData) {
    const user = new UserModel({
      ...userData,
      org_id: this.orgId  // CRITICAL: Always set org_id
    });

    await user.save();
    return user;
  }

  async update(id, updates) {
    // Prevent changing org_id
    delete updates.org_id;

    const user = await UserModel.findOneAndUpdate(
      { _id: id, org_id: this.orgId },  // CRITICAL: Filter by org_id
      updates,
      { new: true, runValidators: true }
    ).select('-password');

    if (!user) {
      throw new NotFoundError('User');
    }

    return user;
  }

  async delete(id) {
    const result = await UserModel.deleteOne({
      _id: id,
      org_id: this.orgId  // CRITICAL: Filter by org_id
    });

    if (result.deletedCount === 0) {
      throw new NotFoundError('User');
    }

    return true;
  }
}

// Usage in controller
export async function listUsers(req, res, next) {
  try {
    const repository = new UserRepository(req.user.orgId);
    const result = await repository.findAll(
      { status: 'active' },
      { page: req.query.page, limit: req.query.limit }
    );

    res.json(result);
  } catch (error) {
    next(error);
  }
}
